<?php require '../config/database.php';auth();if(($_SESSION['role']??'')!=='admin')die('ليس لديك صلاحية');if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('INSERT INTO users(username,password,full_name,role) VALUES(?,?,?,?)');$s->execute([$_POST['username'],password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['full_name'],$_POST['role']]);header('Location:index.php');exit;}?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>إضافة مستخدم</h1><form method="post"><label>اسم المستخدم</label><input name="username" required><label>الاسم الكامل</label><input name="full_name" required><label>كلمة المرور</label><input type="password" name="password" required><label>الدور</label><select name="role"><option value="employee">موظف</option><option value="admin">مدير</option></select><button>حفظ</button></form></main>
